from fastapi.testclient import TestClient
from main import app

client = TestClient(app, raise_server_exceptions=True)

def test_post_missing_required_field_returns_422_no_location():
    payload = {
        "firstName": "NoPosition",
        "lastName": "Player",
        "squadNumber": 88
    }
    r = client.post("/players/", json=payload)
    assert r.status_code == 422
    header_keys_lower = {k.lower() for k in r.headers}
    assert "location" not in header_keys_lower
